// Единая подпись субтитров по-английски (сессия 15a2, решения 276, 292): «English», «English (auto-generated)»,
// «Ukrainian (auto-translated)».
//
// Одну и ту же подпись должны видеть две стороны, иначе память выбора не найдёт язык по подписи (14b2):
// - пункты нашего меню субтитров YouTube (`sites/youtube/variants.ts`);
// - скачанный документ timedtext (`sites/youtube/timedtext-naming.ts` и `track-naming.ts` фона).
// Поэтому функция чистая и живёт в общей способности: ни сети, ни DOM, ни состояния.

/** Что известно о дорожке субтитров, чтобы подписать её. */
export interface CaptionLabelParts {
  /** Тег языка (`en`, `zh-Hans`); `null` — язык неизвестен. */
  readonly language: string | null;
  /** Дорожку распознал сам сайт (автосубтитры). */
  readonly autoGenerated: boolean;
  /** Текст дорожки переведён сайтом на лету (автоперевод). */
  readonly autoTranslated: boolean;
  /** Название дорожки у сайта («British», «Lyrics»), если им надо отличить дорожки одного языка. */
  readonly trackName?: string;
}

/** Хвосты подписи после названия языка. */
const AUTO_GENERATED_SUFFIX = "(auto-generated)";
const AUTO_TRANSLATED_SUFFIX = "(auto-translated)";

/** Слова вместо названия языка, когда его нет: «Auto-generated», «Auto-translated»; у ручной дорожки — пусто. */
const AUTO_GENERATED_WITHOUT_LANGUAGE = "Auto-generated";
const AUTO_TRANSLATED_WITHOUT_LANGUAGE = "Auto-translated";

/** Словарь названий создаём один раз: `Intl.DisplayNames` дорого строить, а подписей в меню сотни. */
let languageNames: Intl.DisplayNames | undefined;

/** Английское название языка по тегу; `undefined` — у браузера названия нет или тег негоден для `Intl`. */
export function englishLanguageName(language: string | null): string | undefined {
  if (language === null) return undefined;
  try {
    languageNames ??= new Intl.DisplayNames(["en"], { type: "language", fallback: "none" });
    return languageNames.of(language);
  } catch (error) {
    // Тег прошёл проверку длины, но не годится для Intl (RangeError): названия нет. Прочее — наш баг.
    if (error instanceof RangeError) return undefined;
    throw error;
  }
}

/**
 * Подпись дорожки. Порядок: название языка, название дорожки сайта в скобках, потом признак машины
 * (перевод главнее распознавания: переведённый текст зритель называет переводом).
 * Пустая строка — подписать нечем (ручная дорожка неизвестного языка без названия): решает вызывающий.
 */
export function captionLabelOf(parts: CaptionLabelParts): string {
  const languageName = englishLanguageName(parts.language);
  const machineSuffix = parts.autoTranslated ? AUTO_TRANSLATED_SUFFIX : parts.autoGenerated ? AUTO_GENERATED_SUFFIX : undefined;
  if (languageName === undefined) {
    // Без названия языка признак машины остаётся словом, а название дорожки сайта — единственным различием.
    const machineWords = parts.autoTranslated ? AUTO_TRANSLATED_WITHOUT_LANGUAGE : parts.autoGenerated ? AUTO_GENERATED_WITHOUT_LANGUAGE : undefined;
    return [parts.trackName, machineWords].filter((word) => word !== undefined && word !== "").join(" ");
  }
  const named = parts.trackName === undefined || parts.trackName === "" ? languageName : `${languageName} (${parts.trackName})`;
  return machineSuffix === undefined ? named : `${named} ${machineSuffix}`;
}

/**
 * Подпись пункта автоперевода на язык `language` (меню субтитров сайта, решение 293): английское название
 * языка и метка «(auto-translated)»; браузер не знает названия — вместо него сам код («aa (auto-translated)»),
 * но метка остаётся всегда: по ней плеер отличает переводы от родных дорожек (клавиша V).
 */
export function translationCaptionLabel(language: string): string {
  const languageName = englishLanguageName(language) ?? language;
  return `${languageName} ${AUTO_TRANSLATED_SUFFIX}`;
}
